/* Inspire Talent Hub — Premium authored question bank: Class 10 Science (CBSE).
 * Chemistry cluster: Acids Bases & Salts · Metals & Non-metals · Carbon & Its Compounds.
 * Original, educator-grade items (see qbank-science-10.js for the schema). */
window.ITH_QBANK = window.ITH_QBANK || {};

window.ITH_QBANK['cbse|10|science|acids-bases-and-salts'] = {
  mcq: [
    { q: 'A solution turns red litmus blue. The solution is:', o: ['Basic', 'Acidic', 'Neutral', 'Always distilled water'], a: 0, d: 1, e: 'Bases turn red litmus blue.' },
    { q: 'When zinc reacts with dilute sulphuric acid, the gas evolved is:', o: ['Hydrogen', 'Oxygen', 'Carbon dioxide', 'Chlorine'], a: 0, d: 1, e: 'Zn + H₂SO₄ → ZnSO₄ + H₂; the gas burns with a pop.' },
    { q: 'The pH of a neutral solution at 25 °C is:', o: ['7', '0', '14', '1'], a: 0, d: 1, e: 'Neutral solutions have pH 7.' },
    { q: 'A solution turns phenolphthalein pink. Its pH could be:', o: ['10', '5', '7', '3'], a: 0, d: 2, e: 'Phenolphthalein is pink only in basic (pH > 7) solutions.' },
    { q: 'The best substance to relieve indigestion due to excess stomach acid is:', o: ['A mild base (antacid)', 'A strong acid', 'Common salt', 'Vinegar'], a: 0, d: 2, comp: true, e: 'Antacids are mild bases that neutralise excess HCl.' },
    { q: 'Bleaching powder is made by the action of chlorine on:', o: ['Dry slaked lime', 'Quicklime', 'Washing soda', 'Baking soda'], a: 0, d: 2, e: 'Ca(OH)₂ + Cl₂ → CaOCl₂ + H₂O.' },
    { q: 'The chemical formula of Plaster of Paris is:', o: ['CaSO₄·½H₂O', 'CaSO₄·2H₂O', 'CaSO₄', 'Ca(OH)₂'], a: 0, d: 2, e: 'PoP is calcium sulphate hemihydrate.' },
    { q: 'Tooth decay begins when the pH of the mouth falls below:', o: ['5.5', '7', '9', '2'], a: 0, d: 2, comp: true, e: 'Below pH 5.5 the enamel starts to dissolve.' },
    { q: 'The starting material for the chlor-alkali process is:', o: ['Concentrated sodium chloride solution (brine)', 'Sodium carbonate', 'Sodium bicarbonate', 'Calcium carbonate'], a: 0, d: 2, e: 'Electrolysis of brine gives NaOH, Cl₂ and H₂.' },
    { q: 'Which of the following salts is basic in nature?', o: ['Sodium carbonate', 'Ammonium chloride', 'Sodium chloride', 'Sodium sulphate'], a: 0, d: 3, comp: true, e: 'Na₂CO₃ is the salt of a strong base and a weak acid, so it is basic.' }
  ],
  ar: [
    { A: 'Acids do not show acidic behaviour in the absence of water.', R: 'Acids produce hydrogen ions (H⁺), responsible for acidic behaviour, only in aqueous solution.', a: 0 },
    { A: 'The pH of the human stomach is about 2.', R: 'The stomach produces sodium hydroxide that digests proteins.', a: 2 },
    { A: 'An aqueous solution of baking soda is acidic in nature.', R: 'Sodium hydrogencarbonate is a salt of a strong base and a weak acid, so its solution is mildly basic.', a: 3 }
  ],
  vsa: [
    { q: 'Why does dry HCl gas not change the colour of dry blue litmus paper, whereas hydrochloric acid solution does?', a: 'Dry HCl gas has no free hydrogen ions; acids show acidic behaviour (turning blue litmus red) only when they produce H⁺ (H₃O⁺) ions, which happens in the presence of water.', k: ['no H⁺ ions when dry', 'H⁺/H₃O⁺ formed in water'], cm: 'Saying dry HCl is not an acid — it is, but it must ionise in water.' },
    { q: 'What is a neutralisation reaction? Give one balanced example.', a: 'A reaction between an acid and a base to form salt and water. Example: NaOH + HCl → NaCl + H₂O.', k: ['acid + base → salt + water', 'valid example'], cm: 'Forgetting water as a product.' },
    { q: 'Name the gas evolved when dilute hydrochloric acid reacts with sodium carbonate and state how it is tested.', a: 'Carbon dioxide is evolved. It turns lime water milky: Ca(OH)₂ + CO₂ → CaCO₃ + H₂O.', k: ['carbon dioxide', 'turns lime water milky'], cm: 'Saying hydrogen — carbonates give CO₂, metals give H₂.' },
    { q: 'Why should water never be added to a concentrated acid? State the correct method of dilution.', a: 'Adding water to acid is highly exothermic and can make the acid splash out or crack the container. The concentrated acid should be added slowly to water with constant stirring.', k: ['highly exothermic', 'acid to water, slowly, stirring'], cm: 'Reversing the order (adding water to acid).' },
    { q: 'What is water of crystallisation? Give the formula of washing soda showing it.', a: 'Water of crystallisation is the fixed number of water molecules present in one formula unit of a salt. Washing soda: Na₂CO₃·10H₂O.', k: ['fixed water molecules in a salt', 'Na₂CO₃·10H₂O'], cm: 'Confusing it with surface dampness.' }
  ],
  sa: [
    { q: 'Explain the terms strong acid and weak acid. How does pH help compare their strengths? Give one example of each.', a: 'A strong acid ionises completely in water, giving more H⁺ ions (e.g. HCl); a weak acid ionises only partially, giving fewer H⁺ ions (e.g. acetic acid, CH₃COOH). The lower the pH, the higher the H⁺ concentration and the stronger the acid, so a strong acid has a lower pH than a weak acid of the same concentration.', k: ['complete vs partial ionisation', 'H⁺ concentration', 'lower pH = stronger', 'HCl / CH₃COOH'], cm: 'Confusing strength with concentration.' },
    { q: 'What happens when an acid reacts with a metal? Give a general word equation, a balanced example and the test for the gas produced.', a: 'Acid + metal → salt + hydrogen gas. Example: Zn + 2HCl → ZnCl₂ + H₂. When a burning splint is brought near the gas, it burns with a "pop" sound, confirming hydrogen.', k: ['salt + hydrogen', 'Zn + 2HCl → ZnCl₂ + H₂', 'pop sound test'], cm: 'Saying CO₂ is produced.' },
    { q: 'Describe how bleaching powder is prepared and give two of its uses.', a: 'Bleaching powder is prepared by passing chlorine over dry slaked lime: Ca(OH)₂ + Cl₂ → CaOCl₂ + H₂O. Uses (any two): bleaching cotton and paper, disinfecting drinking water, and acting as an oxidising agent.', k: ['Ca(OH)₂ + Cl₂ → CaOCl₂ + H₂O', 'bleaching', 'disinfecting water'], cm: 'Using quicklime instead of slaked lime.' },
    { q: 'Explain the importance of pH in (i) the human stomach and (ii) tooth decay.', a: '(i) The stomach produces dilute HCl (pH ≈ 2) that helps digestion; excess acid causes acidity, which is treated with antacids (mild bases). (ii) Bacteria in the mouth make acids; when the pH falls below 5.5 the tooth enamel begins to dissolve, causing decay, so basic toothpaste is used to neutralise the acid.', k: ['stomach HCl / antacids', 'enamel dissolves below pH 5.5', 'neutralise with base'], cm: 'Giving the wrong critical pH for tooth decay.' },
    { q: 'How is sodium hydroxide manufactured by the chlor-alkali process? Name the three products and one use of each.', a: 'Electricity is passed through concentrated aqueous sodium chloride (brine): 2NaCl + 2H₂O → 2NaOH + Cl₂ + H₂. Products and uses: NaOH (making soap/paper), Cl₂ (disinfecting water / making PVC), and H₂ (fuel / making ammonia).', k: ['electrolysis of brine', '2NaCl + 2H₂O → 2NaOH + Cl₂ + H₂', 'uses of NaOH, Cl₂, H₂'], cm: 'Saying molten NaCl — the process uses aqueous brine.' },
    { q: 'What is Plaster of Paris? How is it prepared, and why must it be stored in a moisture-proof container?', a: 'Plaster of Paris (CaSO₄·½H₂O) is prepared by heating gypsum (CaSO₄·2H₂O) at about 373 K: CaSO₄·2H₂O → CaSO₄·½H₂O + 1½H₂O. It must be kept dry because it absorbs moisture and sets into hard gypsum, making it useless.', k: ['CaSO₄·½H₂O', 'heat gypsum at 373 K', 'sets to gypsum with water'], cm: 'Heating above 373 K gives useless dead-burnt plaster.' }
  ],
  ma: [
    { q: 'A gardener finds that plants in a bed grow poorly and the soil tests strongly acidic. (a) Why does acidic soil affect growth? (b) Name one substance to correct it and explain how it works. (c) What should he check to avoid over-correcting?', a: '(a) Most plants grow best near a neutral pH; strongly acidic soil harms the roots and locks up nutrients. (b) He can add slaked lime (calcium hydroxide), a base, which neutralises the excess acid and raises the pH. (c) He should re-test the soil pH after treatment so it does not become too basic (alkaline).', k: ['plants need near-neutral pH', 'add base (slaked lime)', 'neutralises acid', 're-test pH'], cm: 'Adding an acid, or not re-testing the pH.' },
    { q: 'A student spills dilute sulphuric acid on the laboratory bench. (a) Which household substance neutralises it and why? (b) Name the type of reaction. (c) Why should a strong base like NaOH not be used? (d) What safety step should follow?', a: '(a) Baking soda (sodium hydrogencarbonate), a mild base, is sprinkled because it neutralises the acid safely. (b) It is a neutralisation reaction. (c) A strong base is corrosive and could itself cause burns/damage. (d) Wash the area with plenty of water and wipe it clean.', k: ['baking soda = mild base', 'neutralisation', 'strong base is corrosive', 'wash with water'], cm: 'Using a strong base or plain water alone on the acid.' },
    { q: 'A soda-acid fire extinguisher releases a gas that puts out fire. (a) Name the two chemicals used. (b) Write the reaction. (c) Name the gas and explain how it stops the fire. (d) Give one situation where it must NOT be used.', a: '(a) Sodium hydrogencarbonate (baking soda) and sulphuric acid. (b) 2NaHCO₃ + H₂SO₄ → Na₂SO₄ + 2H₂O + 2CO₂. (c) The gas is carbon dioxide; being heavier than air and not supporting combustion, it forms a blanket that cuts off oxygen. (d) It must not be used on electrical fires.', k: ['NaHCO₃ + H₂SO₄', 'CO₂', 'blanket cuts off oxygen', 'not on electrical fires'], cm: 'Naming the gas as oxygen or hydrogen.' },
    { q: 'Two colourless solutions A and B are given: A turns blue litmus red and B turns red litmus blue. (a) Identify the nature of A and B. (b) What happens to the pH as B is slowly added to A? (c) Name the products if A is HCl and B is NaOH. (d) How can the end point be shown using temperature alone?', a: '(a) A is acidic and B is basic. (b) As base B is added, H⁺ ions are neutralised, so the pH rises from acidic towards 7 and beyond. (c) NaCl (salt) and water. (d) Neutralisation is exothermic, so the temperature rises to a maximum at the end point and then starts to fall, marking complete neutralisation.', k: ['A acidic, B basic', 'pH rises towards 7', 'NaCl + H₂O', 'exothermic — temperature peaks'], cm: 'Saying the pH falls when a base is added.' }
  ],
  la: [
    { q: 'Compare acids and bases in terms of taste, effect on litmus, ions produced in water, and reaction with metals, with one example for each point.', a: 'Taste: acids are sour (lemon), bases are bitter and soapy (soap). Litmus: acids turn blue litmus red; bases turn red litmus blue. Ions in water: acids produce H⁺ (H₃O⁺) ions (HCl → H⁺ + Cl⁻); bases produce OH⁻ ions (NaOH → Na⁺ + OH⁻). Reaction with metals: acids react with metals to give hydrogen (Zn + 2HCl → ZnCl₂ + H₂); some bases also react with reactive metals to give hydrogen (2NaOH + Zn → Na₂ZnO₂ + H₂).', k: ['taste', 'litmus effect', 'H⁺ vs OH⁻ ions', 'H₂ with metals'], cm: 'Saying only acids can react with metals to give hydrogen.' },
    { q: 'Describe the preparation, properties and uses of baking soda and washing soda, with one balanced equation for each.', a: 'Baking soda (NaHCO₃): made from brine, ammonia and CO₂ (NaCl + H₂O + CO₂ + NH₃ → NaHCO₃ + NH₄Cl). It is a mild, non-corrosive base; on heating it gives CO₂ (2NaHCO₃ → Na₂CO₃ + H₂O + CO₂), so it is used in baking and in antacids. Washing soda (Na₂CO₃·10H₂O): made by heating baking soda to sodium carbonate and recrystallising with water (Na₂CO₃ + 10H₂O → Na₂CO₃·10H₂O). It is used for cleaning, softening hard water, and making glass and soap.', k: ['NaHCO₃ preparation', '2NaHCO₃ → Na₂CO₃ + H₂O + CO₂', 'Na₂CO₃·10H₂O', 'uses of each'], cm: 'Interchanging the uses of the two salts.' },
    { q: 'Explain the concept of pH and the pH scale, and discuss three examples where pH matters in everyday life.', a: 'pH is a number (0–14) showing how acidic or basic a solution is: pH < 7 acidic, 7 neutral, > 7 basic; it depends on the H⁺ concentration — the more H⁺, the lower the pH. Everyday roles: (i) Digestion — the stomach maintains pH ≈ 2 with HCl, and antacids treat excess acid. (ii) Tooth decay — enamel dissolves when the mouth pH falls below 5.5, so basic toothpaste helps. (iii) Soil and crops — plants need near-neutral soil, corrected by adding lime or organic matter. (Bee/nettle stings are also treated with baking soda.)', k: ['pH scale 0–14', 'depends on H⁺ concentration', 'three everyday examples'], cm: 'Saying a higher pH means more acidic.' },
    { q: 'What are salts? Explain how the pH of a salt depends on its parent acid and base, giving one example each of an acidic, basic and neutral salt.', a: 'A salt is the ionic compound formed when the H⁺ of an acid is replaced by a metal (or ammonium) ion during neutralisation. A salt of a strong acid and a strong base is neutral (NaCl, pH 7). A salt of a strong acid and a weak base is acidic (NH₄Cl, pH < 7). A salt of a weak acid and a strong base is basic (Na₂CO₃, pH > 7). So the pH of a salt depends on the relative strengths of its parent acid and base.', k: ['salt from neutralisation', 'strong-strong = neutral', 'strong acid + weak base = acidic', 'weak acid + strong base = basic'], cm: 'Assuming every salt is neutral.' }
  ],
  cs: [
    { p: 'The stomach produces hydrochloric acid, keeping its contents at a pH of about 2. This acid helps to digest food and kills germs. When we eat too much spicy or oily food, the stomach may make excess acid, causing a burning feeling called acidity or heartburn. Doctors advise an antacid — a mild base such as magnesium hydroxide or sodium hydrogencarbonate — which neutralises the extra acid and gives relief without harming the stomach lining.',
      q: [
        { q: 'Why is an antacid a mild base and not a strong base?', a: 'A strong base is corrosive and would harm the delicate stomach lining, so a mild base is used to neutralise the excess acid safely.', m: 2, k: ['strong base corrosive', 'mild base is safe'] },
        { q: 'Write the reaction of stomach acid (HCl) with magnesium hydroxide, name the type of reaction and explain how it relieves acidity.', a: 'Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O. It is a neutralisation reaction; the base neutralises the excess HCl, raising the pH towards normal and relieving the burning sensation.', m: 3, k: ['Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O', 'neutralisation', 'pH raised'], cm: 'Calling it a displacement reaction.' }
      ] },
    { p: 'Our mouth contains many bacteria. After we eat sugary food, these bacteria break the sugar down and produce acids. When the pH inside the mouth falls below 5.5, the acid begins to dissolve the calcium salts of the tooth enamel and tooth decay sets in. Most toothpastes are basic, so brushing with them neutralises the acid and helps to protect the teeth.',
      q: [
        { q: 'At what pH does tooth enamel begin to dissolve, and why?', a: 'Below pH 5.5. At this pH the mouth is acidic enough to dissolve the calcium salts (enamel) of the teeth.', m: 2, k: ['below pH 5.5', 'acid dissolves enamel'] },
        { q: 'Explain how a basic toothpaste helps and suggest one dietary habit that reduces tooth decay.', a: 'A basic toothpaste neutralises the acid made by bacteria, raising the mouth pH above 5.5 so the enamel is protected. Eating less sugary food (or rinsing the mouth after eating) reduces the acid produced and hence the decay.', m: 3, k: ['base neutralises acid', 'pH above 5.5', 'less sugar / rinse'], cm: 'Saying an acidic toothpaste would help.' }
      ] },
    { p: 'Common salt, sodium chloride, is much more than a seasoning — it is the raw material for many useful chemicals. When electricity is passed through its concentrated solution (brine), it gives sodium hydroxide, chlorine and hydrogen, in a process called the chlor-alkali process. Sodium hydroxide is used to make soap, chlorine is used to disinfect water and make bleaching powder, and hydrogen is used as a fuel. Other members of the salt family, such as baking soda and washing soda, are also made starting from common salt.',
      q: [
        { q: 'Name the three products of the chlor-alkali process.', a: 'Sodium hydroxide (NaOH), chlorine (Cl₂) and hydrogen (H₂).', m: 2, k: ['NaOH', 'Cl₂', 'H₂'] },
        { q: 'Why is the process called "chlor-alkali"? Write the balanced equation and give one use of the chlorine produced.', a: 'It is named after its two main products — "chlor" for chlorine and "alkali" for sodium hydroxide. 2NaCl + 2H₂O → 2NaOH + Cl₂ + H₂. The chlorine is used to disinfect drinking water (or to make bleaching powder/PVC).', m: 3, k: ['chlor = chlorine, alkali = NaOH', '2NaCl + 2H₂O → 2NaOH + Cl₂ + H₂', 'use of Cl₂'], cm: 'Forgetting to balance or naming wrong products.' }
      ] }
  ]
};

window.ITH_QBANK['cbse|10|science|metals-and-non-metals'] = {
  mcq: [
    { q: 'The metal that is the most malleable (can be beaten into the thinnest sheets) is:', o: ['Gold', 'Iron', 'Zinc', 'Sodium'], a: 0, d: 2, e: 'Gold and silver are the most malleable metals.' },
    { q: 'A non-metal that is lustrous (shiny) is:', o: ['Iodine', 'Sulphur', 'Phosphorus', 'Carbon (amorphous)'], a: 0, d: 2, e: 'Iodine is a shiny, greyish-black non-metal.' },
    { q: 'Which of the following oxides is amphoteric?', o: ['Aluminium oxide', 'Sodium oxide', 'Magnesium oxide', 'Carbon dioxide'], a: 0, d: 2, e: 'Al₂O₃ reacts with both acids and bases.' },
    { q: 'Sodium metal is stored under kerosene because it:', o: ['Reacts vigorously with air and moisture', 'Dissolves in kerosene', 'Is heavier than kerosene', 'Reacts with kerosene slowly'], a: 0, d: 1, e: 'Na reacts vigorously with O₂/H₂O, so it is kept under kerosene.' },
    { q: 'Heating a sulphide ore strongly in the presence of excess air is called:', o: ['Roasting', 'Calcination', 'Reduction', 'Refining'], a: 0, d: 2, e: 'Roasting converts a sulphide ore to its oxide.' },
    { q: 'Which reddish-brown metal does NOT react with dilute acids to give hydrogen?', o: ['Copper', 'Zinc', 'Iron', 'Magnesium'], a: 0, d: 2, comp: true, e: 'Copper lies below hydrogen in the reactivity series.' },
    { q: 'Aqua regia, which can dissolve gold, is a mixture of concentrated:', o: ['3 parts HCl and 1 part HNO₃', '1 part HCl and 3 parts HNO₃', 'H₂SO₄ and HNO₃', 'HCl and H₂SO₄'], a: 0, d: 2, e: 'Aqua regia = 3 : 1 conc. HCl : conc. HNO₃.' },
    { q: 'Galvanisation protects iron from rusting by coating it with:', o: ['Zinc', 'Tin', 'Copper', 'Aluminium'], a: 0, d: 1, e: 'A layer of zinc protects the iron beneath.' },
    { q: 'Very reactive metals such as sodium and aluminium are extracted by:', o: ['Electrolytic reduction', 'Reduction with carbon', 'Roasting', 'Displacement using iron'], a: 0, d: 2, e: 'They are too reactive to be reduced by carbon.' },
    { q: 'The thermit reaction used to weld railway tracks is between iron(III) oxide and:', o: ['Aluminium', 'Copper', 'Zinc', 'Carbon'], a: 0, d: 2, comp: true, e: 'Fe₂O₃ + 2Al → 2Fe + Al₂O₃ + heat.' }
  ],
  ar: [
    { A: 'Sodium is kept immersed in kerosene.', R: 'Sodium reacts vigorously with the oxygen and moisture of air.', a: 0 },
    { A: 'Copper does not react with dilute hydrochloric acid to liberate hydrogen.', R: 'Copper is more reactive than hydrogen.', a: 2 },
    { A: 'Ionic compounds have low melting points.', R: 'Ionic compounds have strong electrostatic forces between oppositely charged ions.', a: 3 }
  ],
  vsa: [
    { q: 'Why are ionic compounds usually solids with high melting points?', a: 'Ionic compounds have strong electrostatic forces of attraction between oppositely charged ions; a large amount of energy is needed to break these bonds, so they are solids with high melting points.', k: ['strong electrostatic forces', 'much energy to break bonds'], cm: 'Saying they have weak intermolecular forces.' },
    { q: 'What are amphoteric oxides? Give one example.', a: 'Oxides that react with both acids and bases to give salt and water, e.g. aluminium oxide (Al₂O₃) or zinc oxide (ZnO).', k: ['react with acids and bases', 'Al₂O₃ / ZnO'], cm: 'Giving a purely basic oxide such as Na₂O.' },
    { q: 'Distinguish between roasting and calcination.', a: 'Roasting: heating a sulphide ore strongly in excess air to convert it to an oxide. Calcination: heating a carbonate ore strongly in limited air to convert it to an oxide.', k: ['sulphide + excess air', 'carbonate + limited air'], cm: 'Swapping the two definitions.' },
    { q: 'Why does a silver ornament turn black over time? Name the substance formed.', a: 'Silver reacts with hydrogen sulphide (H₂S) in the air to form a black coating of silver sulphide (Ag₂S) — a form of corrosion.', k: ['reacts with H₂S', 'black Ag₂S'], cm: 'Saying it forms silver oxide.' },
    { q: 'Write the reaction of sodium with water and state one observation.', a: '2Na + 2H₂O → 2NaOH + H₂. The reaction is so vigorous and exothermic that the hydrogen produced often catches fire, and the sodium darts about on the surface.', k: ['2Na + 2H₂O → 2NaOH + H₂', 'vigorous / catches fire'], cm: 'Forgetting that the reaction is exothermic and vigorous.' }
  ],
  sa: [
    { q: 'List any three physical properties in which metals differ from non-metals, with an example for each.', a: 'Metals are malleable and ductile (gold, copper) whereas non-metals are brittle (sulphur); metals are good conductors of heat and electricity (copper) while non-metals are insulators (except graphite); metals are lustrous and sonorous (silver) while non-metals are generally dull. (Any three.)', k: ['malleable/ductile vs brittle', 'conductor vs insulator', 'lustrous/sonorous'], cm: 'Forgetting exceptions such as graphite (conducts) and iodine (lustrous).' },
    { q: 'What is the reactivity series? How is it used to predict displacement reactions? Give one example.', a: 'The reactivity series lists metals in decreasing order of reactivity. A more reactive metal displaces a less reactive metal from its salt solution. Example: Zn + CuSO₄ → ZnSO₄ + Cu (zinc is above copper).', k: ['decreasing order of reactivity', 'more reactive displaces less reactive', 'Zn + CuSO₄ → ZnSO₄ + Cu'], cm: 'Reversing the direction of displacement.' },
    { q: 'Explain how a highly reactive metal such as sodium is extracted from its molten chloride.', a: 'Very reactive metals cannot be reduced by carbon, so they are extracted by electrolytic reduction. On passing electricity through molten sodium chloride, sodium is deposited (reduced) at the cathode (Na⁺ + e⁻ → Na) and chlorine is liberated at the anode.', k: ['electrolytic reduction', 'molten NaCl', 'Na deposited at cathode'], cm: 'Saying it is reduced by carbon — it is too reactive.' },
    { q: 'What is corrosion? State the conditions for rusting of iron and two methods of prevention.', a: 'Corrosion is the slow eating away of a metal by the action of air, moisture or chemicals on its surface. Iron rusts in the presence of both oxygen and moisture. It can be prevented by galvanisation (zinc coating), painting/greasing, or alloying (e.g. stainless steel). (Any two.)', k: ['slow eating of metal', 'oxygen + moisture', 'galvanising / painting / alloying'], cm: 'Listing only one condition for rusting.' },
    { q: 'What are alloys? Why are they often preferred to pure metals? Give the composition of any two common alloys.', a: 'An alloy is a homogeneous mixture of a metal with one or more metals or non-metals. Alloys are preferred because they are usually harder, stronger or more corrosion-resistant than the pure metal. Examples: steel (iron + carbon), brass (copper + zinc), bronze (copper + tin). (Any two.)', k: ['homogeneous mixture', 'harder / corrosion-resistant', 'two compositions'], cm: 'Calling an alloy a compound.' },
    { q: 'Explain the amphoteric nature of aluminium oxide with equations for its reaction with an acid and a base.', a: 'Aluminium oxide is amphoteric — it reacts with both acids and bases. With acid: Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O. With base: Al₂O₃ + 2NaOH → 2NaAlO₂ + H₂O. In each case a salt and water are formed.', k: ['reacts with acid and base', 'Al₂O₃ + 6HCl', 'Al₂O₃ + 2NaOH'], cm: 'Showing only one type of reaction.' }
  ],
  ma: [
    { q: 'A metal M is extracted from its sulphide ore. (a) Name the process that converts the sulphide to an oxide. (b) Write a general equation. (c) How is the oxide then converted to the metal? (d) Why is the sulphide first changed to the oxide?', a: '(a) Roasting. (b) 2MS + 3O₂ → 2MO + 2SO₂. (c) The oxide is reduced to the metal, usually by heating with a reducing agent such as carbon (MO + C → M + CO). (d) Metal oxides are much easier to reduce to the metal than sulphides.', k: ['roasting', '2MS + 3O₂ → 2MO + 2SO₂', 'reduction of the oxide', 'oxides easier to reduce'], cm: 'Calling the sulphide-to-oxide step calcination.' },
    { q: 'A student puts iron nails in copper sulphate solution and, separately, copper turnings in iron sulphate solution. (a) In which tube does a reaction occur? (b) Write the equation. (c) Why does the other tube show no reaction? (d) What does this reveal about the reactivity of iron and copper?', a: '(a) A reaction occurs in the tube with iron nails in copper sulphate. (b) Fe + CuSO₄ → FeSO₄ + Cu (the blue colour fades and brown copper deposits). (c) Copper is less reactive than iron, so it cannot displace iron from iron sulphate — no reaction. (d) Iron is more reactive than copper.', k: ['iron in CuSO₄ reacts', 'Fe + CuSO₄ → FeSO₄ + Cu', 'copper cannot displace iron', 'iron more reactive'], cm: 'Expecting copper to displace iron.' },
    { q: 'Railway workers use the thermit reaction to join broken rails. (a) Name the reactants. (b) Write the balanced equation. (c) Why is it suitable for the job? (d) Name the type of reaction.', a: '(a) Iron(III) oxide and aluminium powder. (b) Fe₂O₃ + 2Al → 2Fe + Al₂O₃ + heat. (c) The reaction is highly exothermic and produces molten iron that flows into the gap and welds the rails. (d) It is a displacement (and redox) reaction.', k: ['Fe₂O₃ + Al', 'Fe₂O₃ + 2Al → 2Fe + Al₂O₃', 'exothermic, molten iron', 'displacement / redox'], cm: 'Forgetting that the reaction releases heat / molten iron.' },
    { q: 'Aluminium is a reactive metal, yet it is used for cooking utensils and window frames. (a) Why does it resist corrosion? (b) Name the protective layer. (c) How is this property enhanced industrially? (d) Give one more everyday use based on its properties.', a: '(a) Aluminium reacts with oxygen to form a thin, hard, unreactive oxide layer that clings to the surface and protects the metal beneath from further corrosion. (b) Aluminium oxide (Al₂O₃). (c) The oxide layer is thickened by anodising. (d) It is used for electrical wires or foil because it is light, a good conductor and malleable. (Any valid use.)', k: ['protective oxide layer', 'Al₂O₃', 'anodising', 'light / good conductor use'], cm: 'Saying aluminium does not react with oxygen at all.' }
  ],
  la: [
    { q: 'Describe the general steps in extracting a metal of medium reactivity (such as zinc) from its ore, from concentration to refining, with equations where possible.', a: '(1) Concentration of the ore to remove gangue. (2) Conversion to oxide: a carbonate ore is calcined (ZnCO₃ → ZnO + CO₂) or a sulphide ore is roasted (2ZnS + 3O₂ → 2ZnO + 2SO₂). (3) Reduction of the oxide with carbon: ZnO + C → Zn + CO. (4) Refining of the impure metal, usually by electrolytic refining, to obtain pure zinc.', k: ['concentration', 'calcination / roasting to oxide', 'reduction with carbon', 'electrolytic refining'], cm: 'Using electrolytic reduction — that is for very reactive metals.' },
    { q: 'Explain the formation of sodium chloride as an ionic compound and list four general properties of ionic compounds.', a: 'Sodium (2,8,1) loses one electron to attain a stable octet, forming Na⁺; chlorine (2,8,7) gains that electron to form Cl⁻. The oppositely charged ions are held by strong electrostatic attraction, forming NaCl. Properties: (i) they are crystalline solids, (ii) they have high melting and boiling points, (iii) they are generally soluble in water but not in kerosene/petrol, and (iv) they conduct electricity when molten or in aqueous solution but not in the solid state.', k: ['electron transfer Na → Cl', 'electrostatic attraction', 'high m.p., soluble in water', 'conduct when molten / aqueous'], cm: 'Saying ionic solids conduct electricity in the solid state.' },
    { q: 'What is the reactivity series of metals? Using it, explain (a) which metals react with cold water, (b) which react only with acids, and (c) which occur free in nature, with an example each.', a: 'The reactivity series arranges metals in decreasing order of reactivity. (a) Very reactive metals (K, Na, Ca) react even with cold water: 2Na + 2H₂O → 2NaOH + H₂. (b) Moderately reactive metals (Zn, Fe) do not react with cold water but react with dilute acids: Zn + 2HCl → ZnCl₂ + H₂. (c) The least reactive metals (gold, platinum, silver) are unreactive and occur free (native) in nature.', k: ['decreasing reactivity', 'K/Na react with cold water', 'Zn/Fe react with acids', 'Au/Pt occur free'], cm: 'Saying gold reacts readily with acids.' },
    { q: 'Compare the chemical reactions of metals and non-metals with oxygen, water and acids, giving one example each and stating the nature of the oxides formed.', a: 'With oxygen: metals form basic oxides (2Mg + O₂ → 2MgO, basic), non-metals form acidic oxides (S + O₂ → SO₂, acidic). With water: reactive metals react (2Na + 2H₂O → 2NaOH + H₂) while non-metals generally do not react with water. With acids: metals displace hydrogen (Zn + 2HCl → ZnCl₂ + H₂), whereas non-metals generally do not react with dilute acids. Some metal oxides (Al₂O₃, ZnO) are amphoteric.', k: ['metal oxides basic, non-metal oxides acidic', 'metals give H₂ with acids', 'non-metals unreactive with acids', 'amphoteric exceptions'], cm: 'Saying non-metals also displace hydrogen from acids.' }
  ],
  cs: [
    { p: 'Corrosion silently destroys a large fraction of the metal produced each year. Iron, the most widely used metal, rusts when exposed to air and moisture, forming a flaky reddish-brown coating. Silver develops a black tarnish, and copper turns green over time. To fight corrosion, iron is galvanised with zinc, painted, greased, or converted into corrosion-resistant alloys such as stainless steel.',
      q: [
        { q: 'Name the substances formed when (i) silver and (ii) copper corrode.', a: '(i) Silver forms a black coating of silver sulphide (Ag₂S). (ii) Copper forms a green coating of basic copper carbonate.', m: 2, k: ['Ag₂S', 'green basic copper carbonate'] },
        { q: 'Explain why galvanisation protects iron better than painting when the surface gets scratched.', a: 'Painting only forms a barrier; if it is scratched, the exposed iron rusts. In galvanisation the zinc coating is more reactive than iron, so even when scratched, the zinc corrodes in preference to the iron (sacrificial protection), protecting the iron for longer.', m: 3, k: ['paint = barrier only', 'zinc more reactive', 'sacrificial protection'], cm: 'Treating both as identical barrier methods.' }
      ] },
    { p: 'The method used to extract a metal depends on its position in the reactivity series. Metals at the top, such as sodium, magnesium and aluminium, are very reactive and are obtained by electrolytic reduction of their molten compounds. Metals in the middle, such as zinc, iron and lead, are extracted by reducing their oxides with carbon. Metals at the bottom, such as silver and gold, are so unreactive that they are found free in nature.',
      q: [
        { q: 'Why can aluminium not be extracted by reduction with carbon?', a: 'Aluminium is very reactive (high in the series), so carbon cannot reduce its oxide; it is extracted by electrolytic reduction instead.', m: 2, k: ['very reactive', 'carbon cannot reduce it', 'electrolytic reduction'] },
        { q: 'A metal is found free in nature and does not react with dilute acids. Predict its position in the reactivity series and name two such metals, with a reason.', a: 'It lies at the bottom of the reactivity series (least reactive). Examples: gold and platinum (or silver). Because they are so unreactive, they neither corrode nor react with dilute acids and are found in the native (free) state.', m: 3, k: ['bottom of series / least reactive', 'gold, platinum', 'unreactive, found free'], cm: 'Placing an unreactive metal near the top of the series.' }
      ] },
    { p: 'Pure metals are often too soft or corrode too easily, so they are mixed with other elements to make alloys with improved properties. Adding a little carbon to iron gives steel, which is much harder. Mixing copper with zinc gives brass, and copper with tin gives bronze, both harder and more attractive than pure copper. Stainless steel, an alloy of iron with chromium and nickel, does not rust and is used for cutlery and utensils.',
      q: [
        { q: 'What is an alloy, and why is steel preferred to pure iron for construction?', a: 'An alloy is a homogeneous mixture of a metal with other metals or non-metals. Steel (iron + carbon) is much harder and stronger than pure iron, so it is preferred for construction.', m: 2, k: ['homogeneous mixture', 'steel harder / stronger'] },
        { q: 'Give the composition of brass and bronze, and explain one advantage of using stainless steel for cutlery.', a: 'Brass = copper + zinc; bronze = copper + tin. Stainless steel (iron + chromium + nickel) does not rust or corrode, so the cutlery stays clean, hygienic and shiny even after repeated contact with food and water.', m: 3, k: ['brass = Cu + Zn', 'bronze = Cu + Sn', 'stainless steel is rust-resistant'], cm: 'Confusing the compositions of brass and bronze.' }
      ] }
  ]
};

window.ITH_QBANK['cbse|10|science|carbon-and-its-compounds'] = {
  mcq: [
    { q: 'Carbon forms a very large number of compounds mainly because of:', o: ['Catenation and tetravalency', 'Its metallic character', 'Its ionic bonding', 'Its low melting point'], a: 0, d: 2, e: 'Catenation (self-linking) and four valence bonds give great variety.' },
    { q: 'The number of covalent bonds in a molecule of methane (CH₄) is:', o: ['4', '2', '3', '1'], a: 0, d: 1, e: 'Carbon shares its four electrons with four hydrogen atoms.' },
    { q: 'The compound formed immediately after ethane (C₂H₆) in the alkane series is:', o: ['Propane, C₃H₈', 'Butane, C₄H₁₀', 'Methane, CH₄', 'Ethene, C₂H₄'], a: 0, d: 2, e: 'The next homologue differs by one –CH₂– unit.' },
    { q: 'The functional group present in ethanol is:', o: ['–OH (hydroxyl)', '–COOH (carboxyl)', '–CHO (aldehyde)', '>C=O (ketone)'], a: 0, d: 1, e: 'Ethanol is an alcohol containing the hydroxyl group.' },
    { q: 'Vinegar is a dilute aqueous solution of:', o: ['Ethanoic acid', 'Ethanol', 'Methanoic acid', 'Sulphuric acid'], a: 0, d: 1, e: 'Vinegar is 5–8% ethanoic (acetic) acid.' },
    { q: 'The addition of hydrogen to an unsaturated hydrocarbon using a nickel catalyst is called:', o: ['Hydrogenation', 'Substitution', 'Combustion', 'Saponification'], a: 0, d: 2, e: 'Unsaturated oils are hardened to fats by hydrogenation.' },
    { q: 'Detergents clean better than soaps in hard water because:', o: ['Their calcium and magnesium salts are soluble, so no scum forms', 'They are stronger bases', 'They are cheaper', 'They chemically dissolve grease'], a: 0, d: 3, comp: true, e: 'Detergent salts of Ca²⁺/Mg²⁺ are soluble, so no scum forms.' },
    { q: 'The reaction of ethanoic acid with ethanol to form a sweet-smelling product is called:', o: ['Esterification', 'Neutralisation', 'Oxidation', 'Hydrogenation'], a: 0, d: 2, e: 'Acid + alcohol → ester + water (esterification).' },
    { q: 'Which of the following is an unsaturated hydrocarbon?', o: ['Ethene (C₂H₄)', 'Ethane (C₂H₆)', 'Propane (C₃H₈)', 'Methane (CH₄)'], a: 0, d: 2, e: 'Ethene has a carbon–carbon double bond.' },
    { q: 'Heating ethanol with excess concentrated sulphuric acid at about 443 K converts it to ethene. This is a:', o: ['Dehydration reaction', 'Hydrogenation', 'Substitution', 'Combustion'], a: 0, d: 2, comp: true, e: 'Conc. H₂SO₄ removes water from ethanol, forming ethene.' }
  ],
  ar: [
    { A: 'Carbon forms bonds by sharing electrons.', R: 'Carbon has four electrons in its outermost shell and completes its octet by sharing them.', a: 0 },
    { A: 'Members of a homologous series have the same chemical properties.', R: 'Successive members differ by a –CH₂– unit and hence have different functional groups.', a: 2 },
    { A: 'Soaps work very well for cleaning in hard water.', R: 'Soaps form an insoluble scum with the calcium and magnesium ions of hard water.', a: 3 }
  ],
  vsa: [
    { q: 'Why does carbon form compounds mainly by covalent bonding?', a: 'Carbon has four electrons in its outermost shell. It can neither easily lose nor gain four electrons, so it completes its octet by sharing electrons, forming covalent bonds.', k: ['four valence electrons', 'cannot lose/gain 4 electrons', 'shares electrons'], cm: 'Saying carbon forms ionic bonds.' },
    { q: 'What is a homologous series? State one of its characteristics.', a: 'A homologous series is a family of organic compounds with the same functional group and a general formula, in which successive members differ by a –CH₂– group. A characteristic: members show similar chemical properties.', k: ['same functional group', 'differ by –CH₂–', 'similar chemical properties'], cm: 'Saying members differ by a whole –CH₃ group.' },
    { q: 'Name the products formed when ethanoic acid reacts with sodium hydrogencarbonate.', a: 'Sodium ethanoate (sodium acetate), water and carbon dioxide: CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂ (brisk effervescence).', k: ['sodium acetate', 'CO₂', 'CH₃COOH + NaHCO₃ →'], cm: 'Forgetting the CO₂ (brisk effervescence).' },
    { q: 'What is isomerism? Name the two isomers of butane.', a: 'Isomerism is the phenomenon in which compounds have the same molecular formula but different structures. Butane (C₄H₁₀) exists as n-butane (straight chain) and isobutane / 2-methylpropane (branched chain).', k: ['same formula, different structure', 'n-butane and isobutane'], cm: 'Saying isomers have different molecular formulae.' },
    { q: 'Why is the conversion of ethanol to ethanoic acid called an oxidation reaction?', a: 'Oxygen is added to ethanol using an oxidising agent (such as alkaline KMnO₄ or acidified K₂Cr₂O₇) to convert it into ethanoic acid; since oxygen is added, it is an oxidation reaction.', k: ['oxygen added', 'oxidising agent (KMnO₄)', 'oxidation'], cm: 'Calling it a reduction reaction.' }
  ],
  sa: [
    { q: 'Distinguish between saturated and unsaturated hydrocarbons, with one example each, and state how they can be told apart chemically.', a: 'Saturated hydrocarbons have only single C–C bonds (e.g. ethane, C₂H₆); unsaturated hydrocarbons contain at least one double or triple bond (e.g. ethene, C₂H₄). Unsaturated hydrocarbons decolourise bromine water and burn with a yellow, sooty flame, whereas saturated ones do not readily decolourise bromine water and burn with a clean blue flame.', k: ['single vs double/triple bonds', 'ethane / ethene', 'bromine water test', 'sooty vs blue flame'], cm: 'Saying saturated hydrocarbons decolourise bromine water.' },
    { q: 'What are esters? Write the reaction for the formation of an ester from ethanol and ethanoic acid, and give one use of esters.', a: 'Esters are sweet-smelling organic compounds formed when a carboxylic acid reacts with an alcohol (esterification), usually with conc. H₂SO₄ as catalyst: CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O. Esters are used in perfumes and as flavouring agents.', k: ['acid + alcohol → ester', 'conc. H₂SO₄ catalyst', 'CH₃COOC₂H₅', 'perfumes / flavours'], cm: 'Forgetting water as the by-product.' },
    { q: 'Explain, using the idea of a micelle, how soap cleans a dirty cloth.', a: 'A soap molecule has a long hydrocarbon (hydrophobic) tail and an ionic (hydrophilic) head. In water the tails bury into an oil/grease droplet while the heads face the water, forming a structure called a micelle. This traps the grease, which is then rinsed away with water, cleaning the cloth.', k: ['hydrophobic tail & hydrophilic head', 'micelle traps grease', 'rinsed away'], cm: 'Saying the whole soap molecule dissolves uniformly in water.' },
    { q: 'Why do soaps not work well with hard water, and how do detergents overcome this problem?', a: 'Hard water contains calcium and magnesium ions that react with soap to form an insoluble precipitate called scum, wasting the soap. Detergents have sulphonate/sulphate heads whose calcium and magnesium salts are soluble, so they do not form scum and clean effectively even in hard water.', k: ['Ca²⁺/Mg²⁺ form scum', 'soap wasted', 'detergent salts soluble', 'no scum'], cm: 'Saying detergents are simply stronger soaps.' },
    { q: 'Name and describe the two structural isomers of C₄H₁₀ and explain why they are isomers.', a: 'The two isomers are n-butane, a straight chain CH₃–CH₂–CH₂–CH₃, and isobutane (2-methylpropane), a branched chain with a –CH₃ group on the middle carbon. They are isomers because they have the same molecular formula (C₄H₁₀) but different structural arrangements of atoms.', k: ['n-butane straight chain', 'isobutane branched', 'same formula, different structure'], cm: 'Giving structures with different molecular formulae.' },
    { q: 'Describe the reactions of ethanoic acid with (i) a base and (ii) a carbonate, with balanced equations.', a: '(i) With a base (neutralisation): CH₃COOH + NaOH → CH₃COONa + H₂O. (ii) With a carbonate: 2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂ (brisk effervescence of CO₂).', k: ['neutralisation with NaOH', 'carbonate gives CO₂', 'balanced equations'], cm: 'Forgetting the CO₂ from the carbonate reaction.' }
  ],
  ma: [
    { q: 'A student has two unlabelled bottles, one of ethanol and one of ethanoic acid. (a) How do smell and pH help identify them? (b) Give one chemical test to confirm ethanoic acid. (c) Write the equation for that test. (d) Which one turns blue litmus red?', a: '(a) Ethanoic acid has a sharp vinegar smell and is acidic (turns pH paper towards red); ethanol has a pleasant smell and is nearly neutral. (b) Add sodium hydrogencarbonate — ethanoic acid gives brisk effervescence of CO₂, ethanol does not. (c) CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂. (d) Ethanoic acid turns blue litmus red.', k: ['acid smell / pH', 'NaHCO₃ effervescence test', 'CH₃COOH + NaHCO₃ →', 'ethanoic acid is acidic'], cm: 'Expecting ethanol to fizz with baking soda.' },
    { q: 'Vegetable oils are converted into vanaspati ghee in industry. (a) Name the process. (b) Which type of hydrocarbons are the oils, and what happens to them? (c) Write the general reaction. (d) State one health-related point.', a: '(a) The process is hydrogenation. (b) Oils are unsaturated (contain C=C bonds); hydrogen adds across the double bonds, converting them into saturated fats (semi-solid ghee). (c) Unsaturated oil + H₂ →(Ni catalyst) saturated fat. (d) Saturated fats are less healthy for the heart than unsaturated oils, so excessive intake should be avoided.', k: ['hydrogenation', 'oils unsaturated → saturated', 'Ni catalyst', 'saturated fats less healthy'], cm: 'Saying the oils are saturated to begin with.' },
    { q: 'Ethanol is useful but can be harmful. (a) Write the equation for its complete combustion. (b) Why is it used as a cleaner fuel additive? (c) What is denatured alcohol and why is it made? (d) State one harmful effect of drinking alcohol.', a: '(a) C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O + heat. (b) It burns cleanly, releasing much heat with little smoke, so it is blended with petrol as a cleaner fuel. (c) Denatured alcohol is ethanol made unfit for drinking by adding poisonous substances like methanol and dyes, to prevent its misuse. (d) Drinking alcohol slows body reactions and can damage the liver (any valid effect).', k: ['C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O', 'clean-burning fuel', 'denatured = made unfit to drink', 'harmful effect'], cm: 'Saying denatured alcohol is a different compound from ethanol.' },
    { q: 'A cleaning company finds its soap forms scum and cleans poorly in one town but works well in another. (a) What is the likely difference in the water? (b) Why does scum form? (c) Suggest a product that works in both towns and why. (d) How could the hard water be softened for soap to lather?', a: '(a) The town where soap works poorly likely has hard water (rich in Ca²⁺/Mg²⁺ ions); the other has soft water. (b) Soap reacts with these ions to form an insoluble scum, so little lather forms. (c) A detergent works in both because its calcium/magnesium salts are soluble and do not form scum. (d) The hard water can be softened by boiling (temporary hardness) or by adding washing soda, which removes the Ca²⁺/Mg²⁺ ions.', k: ['hard vs soft water', 'Ca²⁺/Mg²⁺ scum', 'use a detergent', 'soften with washing soda / boiling'], cm: 'Saying detergents are chemically the same as soap.' }
  ],
  la: [
    { q: 'Explain, with reasons and one example each, why carbon forms a very large number of compounds — discuss catenation, tetravalency and the ability to form multiple bonds.', a: 'Carbon forms a huge number of compounds because of: (i) Catenation — carbon atoms link with one another through strong C–C covalent bonds to form long chains, branched chains and rings (e.g. hexane, cyclohexane). (ii) Tetravalency — carbon has four valence electrons and forms four strong covalent bonds with atoms such as hydrogen, oxygen and nitrogen (e.g. CH₄). (iii) Multiple bonds — carbon can form double and triple bonds (e.g. C₂H₄, C₂H₂), increasing the variety. Because C–C and C–H bonds are strong, the compounds are quite stable.', k: ['catenation', 'tetravalency', 'multiple bonds', 'strong, stable bonds'], cm: 'Attributing the large number of compounds to ionic bonding.' },
    { q: 'Describe the physical nature of ethanoic acid and its reactions with (i) a base, (ii) a carbonate and (iii) an alcohol, with balanced equations.', a: 'Ethanoic acid (CH₃COOH) is a colourless liquid with a sharp vinegar smell; a 5–8% aqueous solution is vinegar. Reactions: (i) With a base: CH₃COOH + NaOH → CH₃COONa + H₂O (neutralisation). (ii) With a carbonate: 2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂ (brisk effervescence). (iii) With an alcohol (esterification): CH₃COOH + C₂H₅OH ⇌(conc. H₂SO₄) CH₃COOC₂H₅ + H₂O, giving a sweet-smelling ester.', k: ['vinegar / sharp smell', 'neutralisation', 'carbonate → CO₂', 'esterification'], cm: 'Missing the CO₂ or the ester product.' },
    { q: 'What are soaps and detergents? Explain their cleansing action, the structure of a micelle, and why detergents are preferred for washing in hard-water areas.', a: 'Soaps are sodium/potassium salts of long-chain fatty acids; detergents are sodium salts of long-chain sulphonic acids or sulphates. Both molecules have a hydrophobic hydrocarbon tail and a hydrophilic ionic head. In water the tails surround an oil/grease droplet while the heads point outward into the water, forming a micelle that lifts the dirt off and keeps it suspended so it can be rinsed away. Detergents are preferred in hard-water areas because their calcium and magnesium salts are soluble and do not form scum, unlike soaps.', k: ['soap = salt of fatty acid', 'detergent = salt of sulphonic acid', 'micelle: tail in grease, head in water', 'detergent forms no scum'], cm: 'Saying the whole molecule simply dissolves the grease.' },
    { q: 'Explain combustion, oxidation, addition and substitution reactions of carbon compounds, giving one example (with equation) of each.', a: 'Combustion — a carbon compound burns in oxygen releasing heat and light: CH₄ + 2O₂ → CO₂ + 2H₂O + heat. Oxidation — addition of oxygen using an oxidising agent: ethanol → ethanoic acid (CH₃CH₂OH →[O] CH₃COOH). Addition — hydrogen (or other atoms) add across the double bond of an unsaturated compound with a catalyst: C₂H₄ + H₂ →(Ni) C₂H₆. Substitution — in saturated hydrocarbons, an atom is replaced, e.g. by chlorine in sunlight: CH₄ + Cl₂ →(sunlight) CH₃Cl + HCl.', k: ['combustion', 'oxidation (alcohol → acid)', 'addition (hydrogenation)', 'substitution (with Cl₂)'], cm: 'Confusing addition (unsaturated) with substitution (saturated).' }
  ],
  cs: [
    { p: 'Organic compounds can be grouped into families called homologous series. Within a series, every member contains the same functional group and can be represented by a single general formula, and each member differs from the next by a –CH₂– unit. As the chain grows longer, the melting and boiling points increase gradually, but the chemical properties remain very similar because the functional group is unchanged.',
      q: [
        { q: 'What is the general formula of the alkane series, and by what unit do successive members differ?', a: 'The alkane series has the general formula CₙH₂ₙ₊₂, and successive members differ by a –CH₂– unit.', m: 2, k: ['CₙH₂ₙ₊₂', 'differ by –CH₂–'] },
        { q: 'Why do members of a homologous series show similar chemical properties but a gradual change in physical properties?', a: 'They show similar chemical properties because every member has the same functional group, which decides chemical behaviour. Their physical properties (melting/boiling point, state) change gradually because the carbon-chain length — and hence the molecular mass — increases steadily down the series.', m: 3, k: ['same functional group → similar chemistry', 'increasing chain length → changing physical properties'], cm: 'Saying both chemical and physical properties stay identical.' }
      ] },
    { p: 'Ethanol and ethanoic acid are two of the most important carbon compounds in everyday life. Ethanol is the alcohol present in alcoholic drinks and is also used as a solvent and a fuel additive. Ethanoic acid, a 5–8% solution of which is vinegar, is used as a food preservative. Although both contain carbon, hydrogen and oxygen, their functional groups are different, which gives them very different chemical behaviour.',
      q: [
        { q: 'Name the functional group present in (i) ethanol and (ii) ethanoic acid.', a: '(i) Ethanol contains the hydroxyl group, –OH. (ii) Ethanoic acid contains the carboxyl group, –COOH.', m: 2, k: ['–OH', '–COOH'] },
        { q: 'Give one chemical test that distinguishes ethanoic acid from ethanol, with the equation, and state one use of each compound.', a: 'Add sodium hydrogencarbonate: ethanoic acid gives brisk effervescence of CO₂ (CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂), while ethanol does not react. Uses: ethanol as a fuel additive/solvent; ethanoic acid (vinegar) as a food preservative.', m: 3, k: ['NaHCO₃ test', 'CH₃COOH + NaHCO₃ →', 'uses of each'], cm: 'Expecting ethanol to fizz with baking soda.' }
      ] },
    { p: 'Soap molecules are unusual: one end mixes with water while the other end mixes with oil and grease. When soap is added to water containing greasy dirt, the oil-loving ends bury themselves in the grease while the water-loving ends stay in the water. This forms tiny ball-like structures that keep the grease suspended in water so that it can be rinsed away. These structures are the reason soap is able to clean.',
      q: [
        { q: 'Name the two ends of a soap molecule and state what each is attracted to.', a: 'A soap molecule has a hydrophobic (hydrocarbon) tail attracted to oil/grease, and a hydrophilic (ionic) head attracted to water.', m: 2, k: ['hydrophobic tail → grease', 'hydrophilic head → water'] },
        { q: 'Name the ball-like structures described and explain how they remove grease from a dirty cloth.', a: 'They are called micelles. The hydrophobic tails point inward into the grease droplet and the hydrophilic heads point outward into the water, so the grease is trapped inside the micelle and lifted off the cloth; the micelles stay suspended in water and are washed away during rinsing.', m: 3, k: ['micelle', 'tails in grease, heads in water', 'grease suspended and rinsed away'], cm: 'Saying soap chemically dissolves the grease.' }
      ] }
  ]
};
